-- Section 5: quick check
SELECT (SELECT COUNT(*) FROM dbo.Region) AS Regions, (SELECT COUNT(*) FROM dbo.Site) AS Sites,
       (SELECT COUNT(*) FROM dbo.Asset) AS Assets, (SELECT COUNT(*) FROM dbo.Ticket) AS Tickets,
       (SELECT COUNT(*) FROM dbo.TicketAcl) AS AclEntries;
